            &ReleaseReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => {
            let released = capability.intent().decision.entries.len();
            match &receipt {
                Some(path) => emit_line(&format!(
                    "Released {released} package(s); receipt saved to {}",
                    path.display()
                ))?,
                None => emit_line(&format!("Released {released} package(s)"))?,
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

/// Writes a `release --dry-run` preview of `plan`; `init` shows the same one.
pub(crate) fn write_release_preview(
    plan: Option<&LocalReleasePlan>,
    format: OutputFormat,
    out: &mut dyn std::io::Write,
) -> Result<(), CliError> {
    match (plan, format) {
        (None, OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            true,
        )?,
        (None, OutputFormat::Text) => writeln!(out, "{NOTHING_TO_RELEASE}")?,
        (Some(plan), OutputFormat::Json) => emit_report(
            &mut &mut *out,
            &ReleaseDryRunReport {
                intent: plan.intent.clone(),
                diagnostics: plan.diagnostics.clone(),
            },
            true,
        )?,
        (Some(plan), OutputFormat::Text) => {
            write!(out, "{}", render_release_plan(&plan.intent, crate::color::enabled()))?
        }
    }
    if let Some(plan) = plan {
        if plan.tags_unbound {
            eprintln!("{TAGS_UNBOUND_NOTE}");
        }
        for diagnostic in &plan.diagnostics {
            eprintln!("warning: {}", diagnostic.message);
        }
    }
    Ok(())
}

fn print_nothing_to_release(global: &GlobalArgs) -> Result<(), CliError> {
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseNothingReport {
                nothing_to_release: true,
            },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,

